// ── ВИДЫ СМЕТ (banya | house | пользовательские) ──
// Единый источник видов для раздела «Сметы» и формы шаблона. Синхронизируется
// через work_id "estKinds" (как EST_STAGES). seedFrom — разовая копия смет из
// другого вида при первом появлении (одноразово, флаг settings.seededKinds).
let EST_KINDS=[
  {k:"banya",    n:"Баня",              emoji:"🛁"},
  {k:"house",    n:"Дом",               emoji:"🏠"},
  {k:"minibrus", n:"Бани из минибруса", emoji:"🪵", seedFrom:"banya"}
];
function estKindMeta(k){return EST_KINDS.find(function(x){return x.k===k;})||EST_KINDS[0];}
function estKindLabel(k){var m=estKindMeta(k);return m.emoji+" "+m.n;}
// Разовый посев нового вида копией смет вида-источника (seedFrom). Идемпотентно:
// помечаем выполненные виды в settings.seededKinds → не копируем повторно и не
// размножаем между устройствами. Источник пуст → откладываем (флаг не ставим).
// Копия ВСЕХ смет одного вида в другой (id новые, содержимое независимое, этап сохраняется).
// Один источник правды для трёх мест: разовый посев seedFrom, создание нового вида и
// кнопка «Скопировать сметы из вида». Возвращает число скопированных.
function estCopyKindInto(srcKind, dstKind){
  var src=estimates.filter(function(e){return (e.kind||"banya")===srcKind;});
  if(!src.length)return 0;
  var copies=src.map(function(e){var c=JSON.parse(JSON.stringify(e));c.id=gid();c.kind=dstKind;return c;});
  estimates=estimates.concat(copies);
  return copies.length;
}
function estKindCount(k){return estimates.filter(function(e){return (e.kind||"banya")===k;}).length;}

function ensureEstKindSeeds(){
  if(!Array.isArray(settings.seededKinds))settings.seededKinds=[];
  var changed=false;
  EST_KINDS.forEach(function(kd){
    if(!kd.seedFrom)return;
    if(settings.seededKinds.indexOf(kd.k)>=0)return;                       // уже посеян
    if(estimates.some(function(e){return (e.kind||"banya")===kd.k;})){     // уже есть свои сметы — не трогаем
      settings.seededKinds.push(kd.k); changed=true; return;
    }
    if(!estCopyKindInto(kd.seedFrom, kd.k))return;                         // источник пуст — попробуем позже
    settings.seededKinds.push(kd.k); changed=true;
  });
  return changed;
}
// Чистовой этап (на нём сметы разбиваются по комнатам). По флагу finish, а не по n===3 —
// чтобы этапы можно было добавлять/удалять, не ломая привязку комнат.
function isFinishStage(n){var s=EST_STAGES.find(function(x){return x.n===Number(n);});return !!(s&&s.finish);}
function estFinishN(){var s=EST_STAGES.find(function(x){return x.finish;});return s?s.n:0;}
// Эмодзи карточки сметы по ключевым словам названия; фолбэк — эмодзи этапа, затем 🧾.
const EST_EMOJI_RULES=[
  [/контейнер|модул/,"📦"],[/двер|окн/,"🚪"],[/аренд|площад/,"🏗️"],
  [/тёплый пол|теплый пол/,"♨️"],[/подвес|обрешёт|обрешет|каркас|брус|рейк/,"🪜"],
  [/усилен|проём|проем/,"🔩"],[/электр|розетк|выключ|кабел|щит|автомат/,"⚡"],
  [/вод|сантех|канализ|труб|гидроизол/,"🚰"],[/пол|стяжк|осп|наливн/,"🪵"],
  [/утепл|эппс|ппу|изоляц|вата/,"🧊"],[/плитк|spc|кафел/,"🟫"],
  [/краск|фасад|покрас|грунт/,"🎨"],[/вентил|клапан|вытяж/,"🌬️"],
  [/потол|вагонк/,"🪚"],[/перегород|стен/,"🧱"],[/парн|сауна|печ|камин/,"🔥"],
  [/кровл|крыш/,"🏠"],[/свет|освещ|люстр/,"💡"],[/мебел|шкаф/,"🪑"],[/доставк/,"🚚"]
];
function estEmoji(e){
  var s=((e&&e.name)||"").toLowerCase();
  for(var i=0;i<EST_EMOJI_RULES.length;i++){ if(EST_EMOJI_RULES[i][0].test(s)) return EST_EMOJI_RULES[i][1]; }
  var st=EST_STAGES.find(function(x){return x.n===Number(e&&e.stage);});
  return st?st.emoji:"🧾";
}
// Комнаты для разбивки чистового этапа (этап 3). e.room — назначенная комната; иначе
// определяем по названию (один матч → комната, несколько/ноль → «Общие»).
const ROOMS_BANYA=[
  {k:"parnaya",  n:"Парная",        emoji:"🔥", color:"#e67e22"},
  {k:"dushevaya",n:"Душевая",       emoji:"🚿", color:"#2980b9"},
  {k:"tualet",   n:"Туалет",        emoji:"🚽", color:"#16a085"},
  {k:"ko",       n:"Комната отдыха",emoji:"🛋", color:"#8e44ad"},
  {k:"travyanaya",n:"Травяная",     emoji:"🌿", color:"#27ae60"},
  {k:"obshchie", n:"Общие",         emoji:"🏗️", color:"#7a9aaa"}
];
const ROOMS_HOUSE=[
  {k:"zal",      n:"Зал",           emoji:"🛋", color:"#8e44ad"},
  {k:"spalnya",  n:"Спальня",       emoji:"🛏", color:"#2980b9"},
  {k:"sanuzel",  n:"Сан узел",      emoji:"🚽", color:"#16a085"},
  {k:"koridor",  n:"Коридор",       emoji:"🚪", color:"#e67e22"},
  {k:"obshchie", n:"Общие",         emoji:"🏗️", color:"#7a9aaa"}
];
// Переопределения комнат по видам смет (синхронизируется work_id "estRooms"):
// нет ключа вида — действует дефолт (дом → ROOMS_HOUSE, остальные → ROOMS_BANYA).
let EST_ROOMS={};
function roomsFor(kind){ var c=EST_ROOMS[kind]; return (Array.isArray(c)&&c.length)?c:(kind==="house"?ROOMS_HOUSE:ROOMS_BANYA); }
// Перед первым редактированием комнат вида — материализуем копию дефолта.
function ensureKindRooms(kind){ if(!Array.isArray(EST_ROOMS[kind]))EST_ROOMS[kind]=roomsFor(kind).map(function(r){return {k:r.k,n:r.n,emoji:r.emoji,color:r.color};}); }
const ROOMS_EST=ROOMS_BANYA; // по умолчанию — баня (обратная совместимость)
// Площадь помещения для чистовой работы: по комнате (e.room) и типу из названия (стены/пол/потолок).
function workFillArea(e, specs, kind){
  if(!specs||!Array.isArray(specs.rooms))return null;
  var rk=estRoom(e, kind);
  if(rk==="obshchie")return null;
  var room=specs.rooms.find(function(r){ return estRoom({name:r.name}, kind)===rk; });
  if(!room)return null;
  var s=(e.name||"").toLowerCase(), type=null;
  if(/потол/.test(s))type="ceil";
  else if(/стен/.test(s))type="wall";
  else if(/(?:^|[^а-яё])пол[аы]?(?:[^а-яё]|$)/.test(s)||/напольн/.test(s))type="floor";  // кириллице-безопасно: пол/пола/полы, но не «полки/полков»
  if(!type)return null;
  var c=specRoomCalc(room, specs.height);
  var v=c[type];
  if(!(v>0))return null;
  return { type:type, value:v, room:room.name, label:(type==="wall"?"стены":type==="floor"?"пол":"потолок") };
}
function estRoom(e, kind){
  // Сохранённую комнату используем, только если она из набора текущего типа (баня/дом).
  // Иначе (напр. дом-смета скопирована из бани с банными ключами) — определяем по названию,
  // чтобы работа не выпала из группировки.
  if(e&&e.room&&roomsFor(kind).some(function(rm){return rm.k===e.room;}))return e.room;
  var s=((e&&e.name)||"").toLowerCase(), hits=[];
  if(kind==="house"){
    if(/зал|гостин/.test(s))hits.push("zal");
    if(/спальн/.test(s))hits.push("spalnya");
    if(/санузел|сан\s*узел|туалет|ванн|унитаз|душев/.test(s))hits.push("sanuzel");
    if(/коридор|прихож|тамбур|холл/.test(s))hits.push("koridor");
  } else {
    if(/парн|сауна/.test(s))hits.push("parnaya");
    if(/душев|моечн|\bмойк/.test(s))hits.push("dushevaya");
    if(/туалет|санузел|унитаз/.test(s))hits.push("tualet");
    if(/отдыха|комнат[аы]? отдых|\bко\b/.test(s))hits.push("ko");
    if(/травя?н|фитобоч|фитобар|фитотерап/.test(s))hits.push("travyanaya");
  }
  var r=hits.length===1?hits[0]:"obshchie";
  // Страж: угаданная по названию комната могла быть удалена из набора вида —
  // тогда «Общие», иначе смета выпадет из группировки по комнатам.
  return roomsFor(kind).some(function(rm){return rm.k===r;})?r:"obshchie";
}
